  if (cartItems.length === 0) throw new AppError('Sepetiniz boş', 400);

  // Transaction ile atomik sipariş oluşturma
  const order = await prisma.$transaction(async (tx) => {
    // 1. Stok kontrolü ve kilitleme (SELECT FOR UPDATE)
    for (const item of cartItems) {
      const product = await tx.product.findUnique({
        where: { id: item.productId },
      });

      if (!product) {
        throw new AppError(`Ürün bulunamadı: ${item.name}`, 404);
      }

      if (product.stock < item.quantity) {
        throw new AppError(
          `${item.name} için yeterli stok yok (Stok: ${product.stock}, İstenen: ${item.quantity})`,
          400
        );
      }
    }

    // 2. Toplam hesapla
    const totalAmount = cartItems.reduce(
      (sum, item) => sum + item.price * item.quantity, 0
    );

    // 3. Sipariş oluştur
    const newOrder = await tx.order.create({
      data: {
        userId,
        totalAmount,
        shippingAddress,
        status: 'PENDING',
        items: {
          create: cartItems.map((item) => ({
            productId: item.productId,
            quantity: item.quantity,
            unitPrice: item.price,
          })),
        },
      },
      include: { items: { include: { product: true } } },
    });

    return newOrder;
  }, {
    isolationLevel: Prisma.TransactionIsolationLevel.Serializable,
  });

  return order;
}

